CREATE TABLE IF NOT EXISTS shadow_experiments(id bigserial PRIMARY KEY,experiment_id text UNIQUE,target_trades integer NOT NULL DEFAULT 10000,target_asset text NOT NULL DEFAULT 'USD/CAD',phase text NOT NULL DEFAULT 'DISCOVERY',status text NOT NULL DEFAULT 'RUNNING',valid_settled_trades integer NOT NULL DEFAULT 0,discovery_count integer NOT NULL DEFAULT 0,validation_count integer NOT NULL DEFAULT 0,unique_market_events integer NOT NULL DEFAULT 0,evaluations integer NOT NULL DEFAULT 0,frozen_strategy_versions jsonb,validation_started_at bigint,started_at bigint NOT NULL,last_trade_at bigint,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS shadow_trades(id bigserial PRIMARY KEY,trade_id text UNIQUE,experiment_id text,market_event_id text,strategy_version text,decision text,confidence numeric,p_buy numeric,p_sell numeric,p_wait numeric,probability_source text,regime text,reference_price numeric,reference_price_observation_id text,reference_timestamp bigint,settlement_target_at bigint,settlement_price numeric,settlement_price_observation_id text,settlement_observed_at bigint,result text,session_id text,market_context_id text,segment_id text,asset_canonical text,market_type text,created_at bigint,settled_at bigint,phase text);
CREATE UNIQUE INDEX IF NOT EXISTS shadow_trades_event_strategy_idx ON shadow_trades(market_event_id,strategy_version);
CREATE INDEX IF NOT EXISTS shadow_trades_unsettled_idx ON shadow_trades(result,settlement_target_at);
CREATE TABLE IF NOT EXISTS shadow_experiment_checkpoints(id bigserial PRIMARY KEY,experiment_id text,at_trade integer,metrics jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(experiment_id,at_trade));
